CREATE TABLE Equipment (
    Equipment_ID INTEGER PRIMARY KEY,
    Model VARCHAR(255),
    Name VARCHAR(255),
    Usage_Status VARCHAR(255)
);

CREATE TABLE Maintenance_Personnel (
    Email VARCHAR(255),
    Maintenance_Personnel_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Telephone VARCHAR(255)
);

CREATE TABLE Equipment_Maintenance (
    Equipment_ID INTEGER PRIMARY KEY NOT NULL,
    Maintenance_Personnel_ID INTEGER NOT NULL,
    Maintenance_Result VARCHAR(255),
    Maintenance_Time DATETIME,
    FOREIGN KEY (Equipment_ID) REFERENCES Equipment(Equipment_ID),
    FOREIGN KEY (Maintenance_Personnel_ID) REFERENCES Maintenance_Personnel(Maintenance_Personnel_ID)
);
